using System.Text;
using Microsoft.Data.Sqlite;
using BefundExplorer.Core.Models;
using BefundExplorer.Core.Search;
namespace BefundExplorer.Core.Data;
public sealed class SqliteReportRepository : IReportRepository
{
 const string W="2.0,6.0,3.0,7.0,1.0,5.0,10.0,0.5"; readonly string cs; public string DatabasePath{get;}
 public SqliteReportRepository(string path){if(string.IsNullOrWhiteSpace(path))throw new ArgumentException("Datenbankpfad fehlt.",nameof(path));DatabasePath=Path.GetFullPath(path);cs=new SqliteConnectionStringBuilder{DataSource=DatabasePath,Mode=SqliteOpenMode.ReadOnly,Cache=SqliteCacheMode.Shared}.ToString();}
 public async Task<SearchPage> SearchAsync(SearchRequest r,CancellationToken ct=default){r=r with{Page=Math.Max(1,r.Page),PageSize=Math.Clamp(r.PageSize,1,500)};if(string.IsNullOrWhiteSpace(r.Query))return await Base(r,ct);if(r.Mode==SearchMode.Substring){var n=GermanSearchNormalizer.NormalizeTolerant(r.Query);return n.EnumerateRunes().Count()<3?await Short(r,n,ct):await Fts(r,"befunde_teiltext_v3",SearchMode.Substring,ct);}if(r.Mode==SearchMode.Tolerant)return await Fts(r,"befunde_tolerant_v3",SearchMode.Tolerant,ct);if(r.Mode==SearchMode.Intelligent){var h=await Intelligent(r,ct);return h.TotalCount>0?h:await Fts(r,"befunde_tolerant_v3",SearchMode.Tolerant,ct);}return await Fts(r,"befunde_volltext_v3",r.Mode,ct);}
 public async Task<ReportRecord?> GetByIdAsync(long id,CancellationToken ct=default){await using var c=await Open(ct);await using var q=c.CreateCommand();q.CommandText="SELECT id,modalitaet,studienbeschreibung,titel,klinische_angaben,fragestellung,methodik,befund,beurteilung,originaltext,strukturstatus FROM befunde WHERE id=$id LIMIT 1";q.Parameters.AddWithValue("$id",id);await using var x=await q.ExecuteReaderAsync(ct);return await x.ReadAsync(ct)?new(x.GetInt64(0),S(x,1),S(x,2),S(x,3),S(x,4),S(x,5),S(x,6),S(x,7),S(x,8),S(x,9),S(x,10)):null;}
 public async Task<FilterOptions> GetFilterOptionsAsync(CancellationToken ct=default){await using var c=await Open(ct);var studies=await Strings(c,"SELECT DISTINCT studienbeschreibung FROM befunde WHERE trim(studienbeschreibung)<>'' ORDER BY studienbeschreibung COLLATE NOCASE",ct);var status=await Strings(c,"SELECT DISTINCT strukturstatus FROM befunde WHERE trim(strukturstatus)<>'' ORDER BY strukturstatus COLLATE NOCASE",ct);return new(studies,status,await Scalar(c,"SELECT count(*) FROM befunde WHERE modalitaet='CT'",ct),await Scalar(c,"SELECT count(*) FROM befunde WHERE modalitaet='MR'",ct),await Scalar(c,"SELECT count(*) FROM befunde",ct));}
 async Task<SearchPage> Base(SearchRequest r,CancellationToken ct){await using var c=await Open(ct);var f=Filters(r);var total=await Count(c,$"SELECT count(*) FROM befunde b WHERE {f.sql}",f.p,ct);var sql=$"SELECT b.id,b.modalitaet,b.studienbeschreibung,b.titel,b.klinische_angaben,b.fragestellung,b.befund,b.beurteilung,b.strukturstatus,substr(CASE WHEN trim(b.beurteilung)<>'' THEN b.beurteilung WHEN trim(b.befund)<>'' THEN b.befund ELSE b.originaltext END,1,420),0.0 relevance FROM befunde b WHERE {f.sql} ORDER BY {Order(r.Sort,false)} LIMIT $limit OFFSET $offset";return new(await Rows(c,sql,f.p,r,ct),total,r.Page,r.PageSize);}
 async Task<SearchPage> Intelligent(SearchRequest r,CancellationToken ct){var standard=FtsQueryBuilder.Build(r.Query,SearchMode.AllWords,r.Field);var tokens=GermanSearchNormalizer.Tokenize(r.Query);if(tokens.Count==0||tokens.Any(t=>t.EnumerateRunes().Count()<3))return await Fts(r,"befunde_volltext_v3",SearchMode.AllWords,ct);var sub=FtsQueryBuilder.Build(r.Query,SearchMode.AllWords,r.Field);await using var c=await Open(ct);var f=Filters(r);var p=new Dictionary<string,object?>(f.p){{"$standard",standard},{"$substring",sub}};var cte=$"WITH hits AS (SELECT rowid id,bm25(befunde_volltext_v3,{W}) score FROM befunde_volltext_v3 WHERE befunde_volltext_v3 MATCH $standard UNION ALL SELECT rowid id,bm25(befunde_teiltext_v3,{W})+1000.0 score FROM befunde_teiltext_v3 WHERE befunde_teiltext_v3 MATCH $substring),best AS (SELECT id,min(score) relevance FROM hits GROUP BY id)";var total=await Count(c,$"{cte} SELECT count(*) FROM best JOIN befunde b ON b.id=best.id WHERE {f.sql}",p,ct);var sql=$"{cte} SELECT b.id,b.modalitaet,b.studienbeschreibung,b.titel,b.klinische_angaben,b.fragestellung,b.befund,b.beurteilung,b.strukturstatus,substr(CASE WHEN trim(b.beurteilung)<>'' THEN b.beurteilung WHEN trim(b.befund)<>'' THEN b.befund ELSE b.originaltext END,1,420),best.relevance FROM best JOIN befunde b ON b.id=best.id WHERE {f.sql} ORDER BY {Order(r.Sort,true)} LIMIT $limit OFFSET $offset";return new(await Rows(c,sql,p,r,ct),total,r.Page,r.PageSize);}
 async Task<SearchPage> Fts(SearchRequest r,string table,SearchMode mode,CancellationToken ct){var match=FtsQueryBuilder.Build(r.Query,mode,r.Field);if(match.Length==0)return new([],0,r.Page,r.PageSize);await using var c=await Open(ct);var f=Filters(r);var p=new Dictionary<string,object?>(f.p){{"$match",match}};var total=await Count(c,$"SELECT count(*) FROM {table} f JOIN befunde b ON b.id=f.rowid WHERE {table} MATCH $match AND {f.sql}",p,ct);var snippet=table=="befunde_tolerant_v3"?"substr(CASE WHEN trim(b.beurteilung)<>'' THEN b.beurteilung WHEN trim(b.befund)<>'' THEN b.befund ELSE b.originaltext END,1,420)":$"snippet({table},-1,'⟦','⟧',' … ',32)";var sql=$"SELECT b.id,b.modalitaet,b.studienbeschreibung,b.titel,b.klinische_angaben,b.fragestellung,b.befund,b.beurteilung,b.strukturstatus,{snippet},bm25({table},{W}) relevance FROM {table} f JOIN befunde b ON b.id=f.rowid WHERE {table} MATCH $match AND {f.sql} ORDER BY {Order(r.Sort,true)} LIMIT $limit OFFSET $offset";return new(await Rows(c,sql,p,r,ct),total,r.Page,r.PageSize);}
 async Task<SearchPage> Short(SearchRequest r,string term,CancellationToken ct){if(term.Length==0)return new([],0,r.Page,r.PageSize);await using var c=await Open(ct);var f=Filters(r);var cols=r.Field==SearchField.All?new[]{"studienbeschreibung","titel","klinische_angaben","fragestellung","methodik","befund","beurteilung","originaltext"}:new[]{Col(r.Field)};var hit=string.Join(" OR ",cols.Select(z=>$"instr(n.{z},$term)>0"));var p=new Dictionary<string,object?>(f.p){{"$term",term}};var total=await Count(c,$"SELECT count(*) FROM befunde_suchnormalisiert n JOIN befunde b ON b.id=n.id WHERE ({hit}) AND {f.sql}",p,ct);var score="-(CASE WHEN instr(n.beurteilung,$term)>0 THEN 10 ELSE 0 END+CASE WHEN instr(n.fragestellung,$term)>0 THEN 7 ELSE 0 END+CASE WHEN instr(n.titel,$term)>0 THEN 6 ELSE 0 END+CASE WHEN instr(n.befund,$term)>0 THEN 5 ELSE 0 END+CASE WHEN instr(n.klinische_angaben,$term)>0 THEN 3 ELSE 0 END+CASE WHEN instr(n.studienbeschreibung,$term)>0 THEN 2 ELSE 0 END+CASE WHEN instr(n.methodik,$term)>0 THEN 1 ELSE 0 END+CASE WHEN instr(n.originaltext,$term)>0 THEN .5 ELSE 0 END)";var sql=$"SELECT b.id,b.modalitaet,b.studienbeschreibung,b.titel,b.klinische_angaben,b.fragestellung,b.befund,b.beurteilung,b.strukturstatus,substr(CASE WHEN trim(b.beurteilung)<>'' THEN b.beurteilung WHEN trim(b.befund)<>'' THEN b.befund ELSE b.originaltext END,1,420),{score} relevance FROM befunde_suchnormalisiert n JOIN befunde b ON b.id=n.id WHERE ({hit}) AND {f.sql} ORDER BY {Order(r.Sort,true)} LIMIT $limit OFFSET $offset";return new(await Rows(c,sql,p,r,ct),total,r.Page,r.PageSize);}
 static (string sql,Dictionary<string,object?> p) Filters(SearchRequest r){var a=new List<string>();var p=new Dictionary<string,object?>();if(r.IncludeCt&&!r.IncludeMr)a.Add("b.modalitaet='CT'");else if(!r.IncludeCt&&r.IncludeMr)a.Add("b.modalitaet='MR'");else if(!r.IncludeCt&&!r.IncludeMr)a.Add("0=1");else a.Add("b.modalitaet IN ('CT','MR')");if(!string.IsNullOrWhiteSpace(r.StudyDescription)){a.Add("b.studienbeschreibung=$study");p["$study"]=r.StudyDescription!.Trim();}if(!string.IsNullOrWhiteSpace(r.StructureStatus)){a.Add("b.strukturstatus=$status");p["$status"]=r.StructureStatus!.Trim();}if(r.HasImpression is true)a.Add("trim(b.beurteilung)<>''");else if(r.HasImpression is false)a.Add("trim(b.beurteilung)=''");return(string.Join(" AND ",a),p);}
 static string Order(SortMode s,bool search)=>s switch{SortMode.OriginalAscending=>"b.id ASC",SortMode.OriginalDescending=>"b.id DESC",SortMode.StudyAscending=>"b.studienbeschreibung COLLATE NOCASE ASC,b.id ASC",_ when search=>"relevance ASC,b.id ASC",_=>"b.id ASC"};
 static string Col(SearchField f)=>f switch{SearchField.StudyDescription=>"studienbeschreibung",SearchField.Title=>"titel",SearchField.ClinicalInformation=>"klinische_angaben",SearchField.Question=>"fragestellung",SearchField.Technique=>"methodik",SearchField.Findings=>"befund",SearchField.Impression=>"beurteilung",_=>"originaltext"};
 async Task<SqliteConnection> Open(CancellationToken ct){var c=new SqliteConnection(cs);await c.OpenAsync(ct);return c;}static async Task<int> Count(SqliteConnection c,string sql,IReadOnlyDictionary<string,object?> p,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText=sql;Params(q,p);return Convert.ToInt32(await q.ExecuteScalarAsync(ct));}static async Task<int> Scalar(SqliteConnection c,string sql,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText=sql;return Convert.ToInt32(await q.ExecuteScalarAsync(ct));}static async Task<List<string>> Strings(SqliteConnection c,string sql,CancellationToken ct){var a=new List<string>();await using var q=c.CreateCommand();q.CommandText=sql;await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))a.Add(r.GetString(0));return a;}
 static async Task<List<ReportSummary>> Rows(SqliteConnection c,string sql,IReadOnlyDictionary<string,object?> p,SearchRequest req,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText=sql;Params(q,p);q.Parameters.AddWithValue("$limit",req.PageSize);q.Parameters.AddWithValue("$offset",(req.Page-1)*req.PageSize);var a=new List<ReportSummary>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))a.Add(new(r.GetInt64(0),S(r,1),S(r,2),S(r,3),S(r,4),S(r,5),S(r,6),S(r,7),S(r,8),S(r,9),r.IsDBNull(10)?0:r.GetDouble(10)));return a;}static void Params(SqliteCommand q,IReadOnlyDictionary<string,object?> p){foreach(var x in p)q.Parameters.AddWithValue(x.Key,x.Value??DBNull.Value);}static string S(SqliteDataReader r,int i)=>r.IsDBNull(i)?"":r.GetString(i);
}
